namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public int InstructorId { get; set; }
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and abstract patterns." },
        new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
        new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events, societies, and civilizations." }
    ];

    private readonly List<Instructor> _instructors =
    [
        new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in distributed systems and cloud computing. She has published over 50 research papers and holds 3 patents.", Email = "achen@university.edu" },
        new() { Id = 2, Name = "Dr. Robert Kim", Title = "Associate Professor of Computer Science", Bio = "Dr. Kim focuses on machine learning and artificial intelligence. He previously worked at a major tech company for 10 years.", Email = "rkim@university.edu" },
        new() { Id = 3, Name = "Dr. Maria Santos", Title = "Professor of Mathematics", Bio = "Dr. Santos is an expert in abstract algebra and number theory with 20 years of teaching experience.", Email = "msantos@university.edu" },
        new() { Id = 4, Name = "Dr. James Wright", Title = "Associate Professor of Physics", Bio = "Dr. Wright researches quantum mechanics and particle physics. He collaborates with CERN on ongoing experiments.", Email = "jwright@university.edu" },
        new() { Id = 5, Name = "Dr. Emily Park", Title = "Professor of English", Bio = "Dr. Park is a published author and literary critic specializing in contemporary American fiction.", Email = "epark@university.edu" },
        new() { Id = 6, Name = "Dr. David Moore", Title = "Professor of History", Bio = "Dr. Moore studies modern European history and has authored three books on World War II.", Email = "dmoore@university.edu" }
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
        new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques. Prerequisites: CS 101.", Credits = 4, Schedule = "Tue/Thu 10:00–11:15 AM", DepartmentId = 1, InstructorId = 1 },
        new() { Id = 3, Code = "CS 310", Title = "Machine Learning", Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and model evaluation.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", DepartmentId = 1, InstructorId = 2, IsFeatured = true },
        new() { Id = 4, Code = "CS 350", Title = "Software Engineering", Description = "Principles of software development including design patterns, testing, version control, and agile methodologies.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", DepartmentId = 1, InstructorId = 2 },
        new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, InstructorId = 3, IsFeatured = true },
        new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to computer science.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", DepartmentId = 2, InstructorId = 3 },
        new() { Id = 7, Code = "MATH 301", Title = "Abstract Algebra", Description = "Groups, rings, and fields. An introduction to algebraic structures and their properties.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:15 PM", DepartmentId = 2, InstructorId = 3 },
        new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, waves, and thermodynamics. Includes laboratory sessions. Corequisite: MATH 101.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 3, InstructorId = 4 },
        new() { Id = 9, Code = "PHYS 201", Title = "Quantum Mechanics", Description = "Introduction to quantum theory, wave functions, Schrödinger equation, and applications to atomic physics.", Credits = 3, Schedule = "Tue/Thu 2:00–3:15 PM", DepartmentId = 3, InstructorId = 4, IsFeatured = true },
        new() { Id = 10, Code = "ENG 101", Title = "College Writing", Description = "Develop academic writing skills through essays, research papers, and peer review. Focus on argumentation and clarity.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 4, InstructorId = 5 },
        new() { Id = 11, Code = "ENG 220", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present, including poetry, fiction, and drama.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", DepartmentId = 4, InstructorId = 5 },
        new() { Id = 12, Code = "HIST 101", Title = "World History I", Description = "Survey of world civilizations from ancient times to 1500 CE. Explores political, cultural, and economic developments.", Credits = 3, Schedule = "Mon/Wed/Fri 2:00–2:50 PM", DepartmentId = 5, InstructorId = 6 },
        new() { Id = 13, Code = "HIST 250", Title = "Modern European History", Description = "Europe from the French Revolution to the present. Covers nationalism, industrialization, world wars, and the EU.", Credits = 3, Schedule = "Tue/Thu 3:30–4:45 PM", DepartmentId = 5, InstructorId = 6, IsFeatured = true }
    ];

    private readonly List<EnrollmentRequest> _enrollments = [];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public void SubmitEnrollment(EnrollmentRequest request) => _enrollments.Add(request);
}

